const wf = $json;
const safeName = (wf.name || 'untitled').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
const path = `workflows/${safeName}-${wf.id}.json`;
const content = Buffer.from(JSON.stringify(wf, null, 2), 'utf-8').toString('base64');
const message = `Backup: ${wf.name} (${new Date().toISOString()})`;
return { json: {
  path, content, message,
  owner_repo: $vars.GITHUB_BACKUP_REPO,
  branch: $vars.GITHUB_BACKUP_BRANCH || 'main',
  workflow_name: wf.name,
  workflow_id: wf.id,
} };

const build = $('Build GitHub File For Workflow').item.json;
const res = $json;
const sha = (res && res.sha) ? res.sha : null;
return { json: { ...build, existing_sha: sha } };

const build = $('Parse Existing Workflow File SHA').item.json;
const res = $json;
const success = !!(res && res.content && res.content.sha);
return { json: {
  workflow_name: build.workflow_name,
  workflow_id: build.workflow_id,
  success,
  error: success ? '' : (res && res.message ? res.message : 'Unknown GitHub error'),
} };

const body = $input.first().json;
const variables = body.data || [];
const path = 'variables-backup.json';
const content = Buffer.from(JSON.stringify(variables, null, 2), 'utf-8').toString('base64');
const message = `Backup: n8n variables (${new Date().toISOString()})`;
return { json: {
  path, content, message,
  owner_repo: $vars.GITHUB_BACKUP_REPO,
  branch: $vars.GITHUB_BACKUP_BRANCH || 'main',
  variable_count: variables.length,
} };

const build = $('Build GitHub File For Variables').item.json;
const res = $json;
const sha = (res && res.sha) ? res.sha : null;
return { json: { ...build, existing_sha: sha } };

const build = $('Parse Existing Variables File SHA').item.json;
const res = $json;
const success = !!(res && res.content && res.content.sha);
return { json: {
  variable_count: build.variable_count,
  success,
  error: success ? '' : (res && res.message ? res.message : 'Unknown GitHub error'),
} };

const items = $input.all().map(i => i.json);
const workflowResultsItem = items.find(i => Array.isArray(i.workflow_results));
const variablesItem = items.find(i => 'variable_count' in i);
const workflowResults = workflowResultsItem ? workflowResultsItem.workflow_results : [];
const failedWorkflows = workflowResults.filter(r => !r.success);
const variablesOk = variablesItem ? !!variablesItem.success : false;
const anyFailed = failedWorkflows.length > 0 || !variablesOk;
return { json: {
  total_workflows: workflowResults.length,
  failed_workflow_count: failedWorkflows.length,
  failed_workflow_names: failedWorkflows.map(r => r.workflow_name).join(', '),
  variables_backed_up: variablesItem ? variablesItem.variable_count : 0,
  variables_ok: variablesOk,
  variables_error: variablesItem ? variablesItem.error : '',
  any_failed: anyFailed,
  backed_up_at: new Date().toISOString(),
} };

const d = $json;
const subject = 'n8n backup: one or more items failed';
const lines = [];
if (d.failed_workflow_count > 0) lines.push(`${d.failed_workflow_count} workflow(s) failed to back up: ${d.failed_workflow_names}`);
if (!d.variables_ok) lines.push(`Variables backup failed: ${d.variables_error}`);
const message = `${lines.join('\n')}\n\n${d.total_workflows - d.failed_workflow_count} of ${d.total_workflows} workflows backed up successfully.\n\nCheck the GitHub backup repository and the n8n execution log for details.`;
return { json: { recipient: $vars.FIRM_STAFF_EMAIL, subject, message } };
